  & DR\,$\downarrow$ & RV\,$\downarrow$ & ET\,$\downarrow$ & CF
  & $\uparrow$ \\
\midrule
\multirow{6}{*}{SciERC}
  & Qwen (U)    & 15.37 & 1.39  & 0.40 & 0.08 & 8.23 \\
  & Qwen (S1)   &  0.93 & 0     & 0    & 9.90 & 8.36 \\
  \cmidrule(l){2-7}
  & Llama (U)   & 13.34 & 0.55  & 0    & 0.24 & 2.68 \\
  & Llama (S1)  &  0.08 & 0     & 0    & 6.56 & 2.54 \\
  \cmidrule(l){2-7}
  & Mistral (U) & 56.94 & 0     & 1.50 & 56.87$^\dagger$ & 3.66 \\
